      "clause_id": "§1",
      "concern_id": "C15",
      "effect": "costs",
      "direction": null,
      "quote": "A landlord of a residential unit may not increase rent by more than 5 percent in any 12-month period.",
      "mechanism": "Restricts property owners' control over their rental properties by limiting their ability to set rent prices at market rates.",
      "certainty": "stated"
    }
  ],
  "analysis": [
    {
      "clause_id": "§1",
      "question_id": "Q1",
      "answer": "Under current law, landlords can raise rent by any amount provided they give 60 days' written notice. This measure replaces that unrestricted ability with a strict 5 percent annual cap, though it exempts units that were first occupied within the last 15 years.",
      "disputed": false
    },
    {
      "clause_id": "§1",
      "question_id": "Q2",
      "answer": "Landlords of units older than 15 years bear an opportunity cost in lost potential revenue if market rental rates rise faster than 5 percent annually.",
      "disputed": false
    },
    {
      "clause_id": "§1",
      "question_id": "Q3",
      "answer": "Existing renters in older units benefit from predictable, capped housing costs. Landlords of these properties bear the cost of limited revenue growth.",
      "disputed": false
    },
    {
      "clause_id": "§1",
      "question_id": "Q4",
      "answer": "Landlords may respond by raising rent by exactly the maximum 5 percent every year rather than making infrequent adjustments, or they may defer maintenance to offset lower revenues. Renters may choose to stay in their current units longer to keep their capped rates, potentially reducing housing turnover.",
      "disputed": false
    },
    {
      "clause_id": "§1",
      "question_id": "Q5",
      "answer": "The measure addresses housing affordability and tenant displacement caused by sudden, massive rent spikes. The strict cap mechanism reaches this problem for incumbent tenants, but may create side effects such as reduced housing turnover or deferred maintenance.",
      "disputed": false
    },
    {
      "clause_id": "§1",
      "question_id": "Q6",
      "answer": "Incumbent renters gain leverage and stability against market pricing pressures. Landlords lose pricing discretion over older rental units.",
      "disputed": false
    },
    {
      "clause_id": "§1",
      "question_id": "Q7",
      "answer": "The effect of rent control on overall investment and housing supply is disputed. Some research finds that capping rents discourages new investment, construction, and property maintenance, leading to a long-term reduction in housing supply. Other research suggests that pairing a cap with a rolling exemption for new construction (such as the 15-year rule in this measure) mitigates negative effects on investment while successfully stabilizing prices for current renters.",
      "disputed": true
    }
  ],
